    # Valid punctuation marks
    valid_punctuation = {
        U+2014: 'EM DASH',
        U+2013: 'EN DASH',
        U+2018: 'LEFT SINGLE QUOTATION MARK',
        U+2019: 'RIGHT SINGLE QUOTATION MARK',
        U+201C: 'LEFT DOUBLE QUOTATION MARK',
        U+201D: 'RIGHT DOUBLE QUOTATION MARK',
        U+2033: 'DOUBLE PRIME'
    }

    def is_surrounded_by_punctuation(word, start_index, end_index):
        # Check if the word is immediately surrounded by a valid punctuation mark
        left_char = text[start_index]
        right_char = text[end_index + 1]

        if left_char in valid_punctuation and right_char in valid_punctuation:
            return True

        # Also check if the word starts or ends at the boundary (though spec says "immediately surrounded")
        # Reinterpret: if the word is adjacent to a punctuation mark on both sides
        if start_index > 0 and text[start_index - 1] in valid_punctuation:
            return True
        if end_index + 1 < len(text) and text[end_index + 2] in valid_punctuation:
            return True

        return False

    result = {}
    for word in search_words:
        if not word:
            continue

        count = 0
        n = len(word)
        for i in range(n):
            # Slide window of length 2
            if i + 1 < n:
                if is_surrounded_by_punctuation(word, i, i + 1):
                    count += 1
        result[word] = count

    return result
