def recursive_insertion_sort(arr, n=None):
    if n is None:
        n = len(arr)
    if n <= 1:
        return arr

    # Recursive case: sort the first n-1 elements
    sorted_part = recursive_insertion_sort(arr[:n-1], n-1)

    # Insert the nth element into the sorted part
    i = 0
    while i < n:
        if arr[i] <= arr[n-1]:
            break
        i += 1

    # Shift elements to make space for the new element
    for j in range(n-1, i-1, -1):
        arr[j] = arr[j-1]

    arr[i] = arr[n-1]

    return sorted_part
