def is_tree(edges):
    """
    edges: List of tuples (u, v) representing undirected edges.
    Returns: True if the graph is a tree, False otherwise.
    """
    n = len(edges)
    if n == 0:
        return True  # Empty graph is technically a tree (0 vertices, 0 edges)

    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check connectivity and number of edges
    visited = set()
    stack = [0]
    visited.add(0)
    parent = {0: -1}

    while stack:
        node = stack.pop()
        for neighbor in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                stack.append(neighbor)

    # In a tree with n nodes, there should be exactly n-1 edges and be connected
    if len(visited) != n:
        return False

    return len(edges) == n - 1
