def length_of_lis(nums):
    if not nums:
        return 0

    n = len(nums)
    # dp[i] = length of LIS ending at index i
    dp = [1] * n

    # Efficient O(n log n) using binary search
    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            dp[i] = dp[i - 1] + 1
        else:
            # Find the first element in dp[0..i-1] that is >= nums[i]
            # and replace it with nums[i] to potentially extend future sequences
            left, right = 0, i - 1
            while left <= right:
                mid = (left + right) // 2
                if dp[mid] >= nums[i]:
                    right = mid - 1
                else:
                    left = mid + 1
            dp[i] = nums[i]

    return max(dp)
