def factorial(n):
    if n == 0 or n == 1:
        return 1

    def add(a, b):
        result = 0
        while b > 0:
            result += 1
            b -= 1
        return result

    # Recursive computation using addition only
    # We compute n! = n * (n-1) * ... * 1
    # Instead of using *, we use add to simulate multiplication.
    def helper(k):
        if k == 0:
            return 1
        # Multiply k * (k-1) * ... * 1
        # Start from k and go down to 1, accumulating product using add
        product = 1
        current = k
        while current > 0:
            product = add(product, current)
            current -= 1
        return product

    return helper(n)
