def decode_integer(b: bytes, signed: bool) -> int:
    if not b:
        raise ValueError("Input bytes must be non-empty.")

    length = b[0]
    if length < 1 or length > 255:
        raise ValueError("First byte is not a valid length indicator.")

    if length == 0:
        raise ValueError("Length indicator cannot be zero.")

    # Ensure we have enough bytes to read
    if len(b) < length + 1:
        raise ValueError("Insufficient bytes to read the integer.")

    # Read the integer value from the remaining bytes
    # Big-endian interpretation
    value = int.from_bytes(b[1:length + 1], byteorder='big')

    if signed:
        # Convert to signed integer
        if value < 0:
            value = -(-value - 1)
        return value
    else:
        # Unsigned interpretation (Python int handles this naturally)
        return value
