def findKthLargest(nums, k):
    # Use a min-heap of size k to keep the k largest elements seen so far.
    import heapq

    # If k is 1, the answer is the maximum element.
    if k == 1:
        return max(nums)

    # Build a min-heap from the first k elements.
    heapq.heapify(nums[:k])

    # Iterate over the remaining elements.
    for num in nums[k:]:
        # If current number is larger than the current root (kth largest so far),
        # replace the root and re-heapify.
        if num > heapq.heappop(nums[:k]):
            heapq.heappush(nums[:k], num)

    # After processing all elements, the root of the heap is the kth largest.
    return heapq.heappop(nums[:k])
