def bfs_shortest_path(obstacle_map, quiet_map, start, end):
    if not obstacle_map or not quiet_map:
        return -1

    rows = len(obstacle_map)
    cols = len(obstacle_map[0])

    if start not in ((r, c) for r in range(rows) for c in range(cols)):
        return -1
    if end not in ((r, c) for r in range(rows) for c in range(cols)):
        return -1

