    end_x, end_y = end

    if obstacle_map[start_x][start_y] == 1 or quiet_map[start_x][start_y] == 1:
        return -1
    if obstacle_map[end_x][end_y] == 1 or quiet_map[end_x][end_y] == 1:
        return -1

    # If start and end are the same, path length is 0
    if start_x == end_x and start_y == end_y:
        return 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = deque([(start_x, start_y, 0)])
    visited = set([(start_x, start_y)])

    while queue:
